import java.util.*;

class Solution {
  public int firstCompleteIndex(int[] arr, int[][] mat) {
    int m = mat.length, n = mat[0].length;
    int[] r = new int[m], c = new int[n], ri = new int[m * n + 1], ci = new int[m * n + 1];
    for (int i = 0; i < m; i++)
      for (int j = 0; j < n; j++) {
        ri[mat[i][j]] = i;
        ci[mat[i][j]] = j;
      }
    for (int k = 0; k < arr.length; k++) {
      int x = arr[k];
      if (++r[ri[x]] == n || ++c[ci[x]] == m) return k;
    }
    return -1;
  }
}
